def move_employees(apps, schema_editor):
    """An order's employee agent becomes that person's entry in Salesmen and
    Purchasers (made, ticked Purchaser, when there is none)."""
    PurchaseOrder = apps.get_model("buying", "PurchaseOrder")
    SalesPerson = apps.get_model("core", "SalesPerson")
    for o in PurchaseOrder.objects.exclude(agent_user=None).select_related("agent_user"):
        u = o.agent_user
        person = SalesPerson.objects.filter(user=u).first()
        if person is None:
            name = (u.full_name or u.email).strip()[:100]
            person = SalesPerson.objects.filter(name__iexact=name, user=None).first()
            if person is None:
                person = SalesPerson.objects.create(
                    name=name, is_purchaser=True, email=u.email, user=u
                )
        if not person.is_purchaser:
            person.is_purchaser = True
            person.save(update_fields=["is_purchaser"])
        o.purchaser = person
        o.save(update_fields=["purchaser"])


